	scwin.checkFirstColumnValues = function() {	
		var tbody = WebSquare.wUnit.getDomById("grd_body_tbody");
		var firstColumnValues = [];
		var rows = tbody.getElementsByTagName("tr");
		for (var i = 0; i < rows.length; i++) {
			var row = rows[i];
			var firstCell = row.getElementsByTagName("td")[0];
			if (firstCell) {
				var input = firstCell.querySelector("input, select");
				if (input) {
					firstColumnValues.push(input.value);
				}
			}
		}
		var expectedValues = ["2", "농구", "야구", "야구", "3"];
		var isMatch = firstColumnValues.length === expectedValues.length && firstColumnValues.every((value, index) => value === expectedValues[index]);
		if (isMatch) {
			console.log("첫 번째 컬럼의 값이 올바릅니다.");
		} else {
			console.log("첫 번째 컬럼의 값이 일치하지 않습니다.");
		}
	}

	scwin.checkFirstColumnValues = function() {	
		var tbody = WebSquare.wUnit.getDomById("grd_body_tbody");
		var rows = Array.from(tbody.getElementsByTagName("tr"));
		var firstColumnValues = [];
		let reVal = false;
		rows.forEach(row => {
			var firstCell = row.getElementsByTagName("td")[0];
			if (firstCell) {
				var input = firstCell.querySelector("input, select");
				if (input) {
					firstColumnValues.push(input.value); 
				}
			}
		});

		var expectedValues = ["2", "농구", "야구", "야구", "3"];
		var isMatch = JSON.stringify(firstColumnValues) === JSON.stringify(expectedValues);

		if (isMatch) {
			console.log("첫 번째 컬럼의 값이 올바릅니다.");
			reVal = true;
		} else {
			console.log("첫 번째 컬럼의 값이 일치하지 않습니다.");
		}
		return reVal;
	}	

	scwin.checkVal = function() {
		return scwin.checkFirstColumnValues();
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_scrollY_div').scrollTop = 200;");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
